 P.setupContentUnit=function(e){if(e.contentInitialized)return;e.contentInitialized=true;e.gearSlots??={};e.usedQuickFloors??=[];const favorites=FAVORITES[e.species]||['guard'];const index=(Number(e.id.replace(/\D/g,''))||1)%favorites.length;e.favoriteRooms=[favorites[index],favorites[(index+1)%favorites.length]];if(!e.boss&&this.random()<.65)e.charms.push('CH'+String(1+Math.floor(this.random()*30)).padStart(2,'0'));const hp=this.charmMod(e,'hp'),mana=this.charmMod(e,'mana');e.maxHp=Math.max(15,Math.round(e.maxHp*(1+hp)));e.hp=e.maxHp;e.maxMana=Math.max(0,Math.round(e.maxMana*(1+mana)));e.mana=e.maxMana;this.setGrade(e,e.elite?1:0,!e.boss&&e.faction==='monster'&&this.random()<.35?Object.keys(VARIANTS)[1+Math.floor(this.random()*6)]:'normal');for(const[id,key]of[['CH25','anchored'],['CH28','armorPierce'],['CH03','trapSense']])if(e.charms.includes(id))this.applyStatus(e,key,0,key==='anchored'?.8:key==='armorPierce'?.2:.35,e);if(e.faction==='hero'){const weapon=e.species==='mage'?'I05':e.species==='priest'?'I06':e.species==='rogue'?'I03':'I01';this.equipItem(e,this.createItem(weapon,e));if(e.elite)this.equipItem(e,this.createItem('I07',e));for(const id of[e.species==='mage'||e.species==='priest'?'I15':'I14',this.random()<.4?'I16':'I17'])if(this.usedSlots(e)<e.capacity)this.createItem(id,e);if(e.role==='scout')this.equipItem(e,this.createItem('I10',e));}if(e.species==='mimic'){e.disguised=true;e.concealed=true;e.order='ambush';}}
