 const damage=P.damage;P.damage=function(e,amount,source=null,ctx={}){let value=amount;if(!source&&this.effect(e,'fireResist')&&ctx.effect==='fire')value*=1-this.effect(e,'fireResist').value;if(ctx.effect==='poison'&&this.effect(e,'venomResist'))value*=1-this.effect(e,'venomResist').value;if(ctx.effect==='burn'&&this.effect(e,'fireResist'))value*=1-this.effect(e,'fireResist').value;if(source){const q=source.qualityPower||1,favorite=this.favorite(source),fate=this.state.deck?.activeFate?.id;value*=q*(1+this.charmMod(source,'attack')+this.gearMod(source,'power'));if(favorite)value*=1+.1*(1+this.charmMod(source,'favorite'))*(fate==='F03'?2:1);else if(fate==='F03'&&source.faction==='monster')value*=.9;if(this.charmMod(source,'soloAttack')&&!this.state.entities.some(a=>a.id!==source.id&&a.faction===source.faction&&a.floorId===source.floorId&&a.status==='active'&&distance(a,source)<4))value*=1+this.charmMod(source,'soloAttack');if(this.charmMod(source,'mageHunter')&&e.castUntil>this.state.time)value*=1+this.charmMod(source,'mageHunter');if(this.effect(e,'evasion')&&!ctx.aoe&&!ctx.secondary&&this.random()<this.effect(e,'evasion').value)return;if(this.effect(e,'block')&&!this.effect(e,'disarm')&&!ctx.aoe&&!ctx.secondary&&this.random()<this.effect(e,'block').value)value*=.5;const pierce=this.effect(source,'armorPierce')?.value||0;if(pierce)ctx={...ctx,pierce};const shield=this.effect(e,'shield');if(shield&&this.effect(source,'sunder'))shield.value=Math.max(0,shield.value-value*this.effect(source,'sunder').value);if(ctx.effect==='burn')value*=1+this.charmMod(source,'burn')+this.gearMod(source,'burn');if(ctx.effect==='frost')value*=1+this.charmMod(source,'frost');if(!this.favorite(source))value*=1+this.charmMod(source,'outsideAttack');if(source.evolutionAttack)value*=1+source.evolutionAttack;}
  if(ctx.effect==='frost')value*=1+this.charmMod(e,'frostWeak');if(ctx.effect==='burn'||ctx.effect==='fire')value*=1+this.charmMod(e,'fireWeak');if(this.effect(e,'brittle'))value*=1.15;value*=Math.max(.5,1-(this.charmMod(e,'armor')+this.gearMod(e,'armor'))*(1-(ctx.pierce||0)));if(this.effect(e,'drenched'))value*=ctx.effect==='burn'||ctx.effect==='fire'?.7:ctx.effect==='frost'?1.2:1;if(this.effect(e,'conductive')&&ctx.element==='lightning')value*=1.4;if(e.species==='mimic'&&value>0){e.disguised=false;e.concealed=false}const before=e.hp;damage.call(this,e,value,source,ctx);const actual=before-e.hp;if(source&&actual>0&&!ctx.secondary){if(this.effect(source,'lifesteal'))this.heal(source,actual*this.effect(source,'lifesteal').value);if(['poison','fire','frost'].includes(source.variant))this.applyStatus(e,source.variant==='poison'?'poison':source.variant==='fire'?'burn':'slow',3,source.variant==='frost'?.25:1,source);if(e.charms.includes('CH24')&&distance(source,e)<3&&this.passiveReady(e,'toxicBlood',6))this.applyStatus(source,'poison',3,1,e);if(this.effect(e,'thorns')&&distance(source,e)<3&&this.passiveReady(e,'thorns',1))this.damage(source,actual*this.effect(e,'thorns').value,e,{secondary:true});if(e.hp>0&&e.hp/e.maxHp<.15&&e.charms.includes('CH30')&&this.passiveReady(e,'feignDeath',45)){this.applyStatus(e,'stealth',3,1,e);this.applyStatus(e,'disarm',3,1,e);e.feignUntil=this.state.time+3}}
 };
