 const seals=P.updateSeals;P.updateSeals=function(){seals.call(this);if(this.state.deck?.activeFate?.id!=='F07')return;for(const r of this.state.rooms.filter(r=>r.sealAt!==null))for(const e of this.roomMonsters(r)){e.fateRoomEntries??=[];const key=this.state.wave+':'+r.id;if(!e.fateRoomEntries.includes(key)){e.fateRoomEntries.push(key);this.applyStatus(e,'stealth',3,1,e)}}};
