 const used=P.usedSlots;P.usedSlots=function(e){return used.call(this,e)+e.inventory.reduce((n,id)=>n+Math.max(0,(this.state.items.find(i=>i.id===id)?.slotCost||1)-1),0)};
 P.equipItem=function(e,item){const d=ITEMS[item?.definitionId];if(!d?.slot||!SPECIES[e.species].capacity)return false;const old=this.state.items.find(i=>i.id===e.gearSlots[d.slot]);if(old){old.location='bag';if(this.usedSlots(e)+(old.slotCost||1)<=e.capacity)e.inventory.push(old.id);else Object.assign(old,{owner:null,x:Math.round(e.x),y:Math.round(e.y),floorId:e.floorId,location:'ground'})}e.inventory=e.inventory.filter(id=>id!==item.id);e.gearSlots[d.slot]=item.id;Object.assign(item,{owner:e.id,x:null,y:null,location:'equipment'});if(d.slot==='weapon')e.equipment={name:d.name,power:2,durability:100,itemId:item.id};if(d.slot==='bag')e.capacity=Math.max(e.capacity,6+(d.capacity||0));if(d.grantSkill&&!e.skillIds.includes(d.grantSkill))e.skillIds.unshift(d.grantSkill);e.statuses=e.statuses.filter(s=>s.gearSlot!==d.slot);for(const[type,value]of Object.entries(d.effects||{})){this.applyStatus(e,type,0,value,e);const status=this.effect(e,type);if(status)status.gearSlot=d.slot}return true};
