 const act=P.act;P.act=function(e,dt){if(e.feignUntil>this.state.time)return;if(e.action==='item'&&e.decision<=0&&!e.itemChannel){this.decide(e);if(e.action!=='item')return act.call(this,e,dt)}if(e.action==='item'){const item=e.target;e.decision-=dt;e.itemChannel=(e.itemChannel||0)+dt;const d=ITEMS[this.state.items.find(i=>i.id===item)?.definitionId];if(!d||this.state.time-(e.lastDamaged||-100)<.4){e.itemChannel=0;e.decision=0;return}if(e.itemChannel>=(d.channel||.1)){this.useItem(e,item);e.itemChannel=0;if(e.action==='item'){e.action='guard';e.decision=0}}return}const previousFloor=e.floorId,previousQuick=e.quickScrolls.length,previousTrap=e.action==='disarm'?this.state.traps.find(t=>t.id===e.target):null,wasDisabled=previousTrap?.disabled;act.call(this,e,dt);if(e.cooldown>0)e.cooldown=Math.max(0,e.cooldown-dt*(this.gearMod(e,'attackSpeed')+this.charmMod(e,'attackSpeed')));if(e.quickScrolls.length<previousQuick)e.usedQuickFloors=[...new Set([...e.usedQuickFloors,previousFloor])];if(previousTrap?.disabled&&!wasDisabled){const kit=e.inventory.map(id=>this.state.items.find(i=>i.id===id)).find(i=>i?.definitionId==='I18');if(kit){kit.charges--;if(kit.charges<=0){e.inventory=e.inventory.filter(id=>id!==kit.id);this.state.items=this.state.items.filter(i=>i!==kit)}}}if(e.species==='mimic'&&e.action==='attack')e.disguised=false;};
