 P.choosePackCard=function(uid){const pack=this.state.deck.pendingPack;if(!pack||pack.chosen.includes(uid)||!pack.cards.some(c=>c.uid===uid))return false;pack.chosen.push(uid);this.state.deck.hand.push(pack.cards.find(c=>c.uid===uid));if(pack.chosen.length>=pack.picks){this.state.deck.history.push({type:pack.type,wave:this.state.wave,chosen:[...pack.chosen]});this.state.deck.pendingPack=null}return true};
