 P.playCard=function(uid,x,y,floorId,targetId=null){const card=this.state.deck.hand.find(c=>c.uid===uid),def=CARDS.find(c=>c.id===card?.definitionId);if(!card||!def||!this.canPrepare())return{ok:false,message:'Cần thẻ trên tay và giai đoạn chuẩn bị không tạm dừng.'};let result;if(def.kind==='room'){const col=Math.round((x-18)/36),row=Math.round((y-16)/30);result=this.build(col,row,def.id,floorId)}else if(def.kind==='creature'){result=this.summon(def.species||def.id,x,y,floorId);if(result.ok){this.setGrade(result.entity,card.quality||0,card.variant||'normal');result.entity.hp=result.entity.maxHp}}else if(['trap','prop'].includes(def.kind))result=this.place(def.id,x,y,floorId);else if(def.kind==='upgrade')result={ok:this.promote(targetId)};else if(def.kind==='item'){const e=this.entity(targetId);if(e?.faction==='monster'&&this.usedSlots(e)+(ITEMS[def.id].slotCost||1)<=e.capacity){this.createItem(def.id,e);result={ok:true}}else result={ok:false,message:'Chọn cư dân có túi còn chỗ.'}}if(result?.ok)this.consumeCard(uid);return result||{ok:false,message:'Không thể dùng thẻ ở đây.'}};
 const build=P.build;P.build=function(col,row,type,floorId=0){if(!this._usingCard)return{ok:false,message:'Mở gói để nhận thẻ phòng, rồi dùng thẻ trên tay.'};return build.call(this,col,row,type,floorId)};
 const play=P.playCard;P.playCard=function(...args){this._usingCard=true;try{return play.apply(this,args)}finally{this._usingCard=false}};
 const addRoom=P.addRoom;P.addRoom=function(...args){const room=addRoom.apply(this,args);Object.assign(room,{owner:'dungeon',level:1,buildingMaxHp:['boss','treasure'].includes(room.type)?300:160,buildingHp:['boss','treasure'].includes(room.type)?300:160,captureProgress:0,reclaimProgress:0,stock:6,pulse:0,serviceTimer:0});room.baseBuildingMaxHp=room.buildingMaxHp;if(room.type==='mimic'){room.loot=30;room.loot=30}return room};
 P.prepareFates=function(){const pool=Object.keys(FATES),picks=[];while(picks.length<3){const id=pool[Math.floor(this.random()*pool.length)];if(!picks.includes(id))picks.push(id)}this.state.deck.fateChoices=picks;this.state.deck.fateChosen=false};
 P.chooseFate=function(id){const s=this.state;if(s.phase!=='result'||s.deck.fateChosen||!s.deck.fateChoices.includes(id))return false;s.deck.activeFate={...FATES[id],wave:s.wave+1};s.deck.fateChosen=true;for(const r of s.rooms){const ratio=r.buildingHp/r.buildingMaxHp;r.buildingMaxHp=Math.round((r.baseBuildingMaxHp+80*(r.level-1))*(id==='F05'?.8:id==='F06'?1.5:1));r.buildingHp=Math.round(r.buildingMaxHp*ratio)}this.log('Định mệnh đã chọn: '+FATES[id].name);return true};
 const next=P.next;P.next=function(){const s=this.state;if(s.phase!=='result'||!s.deck.fateChosen)return false;next.call(this);const recovered=s.deck.discard.splice(0);s.deck.hand.push(...recovered);if(s.deck.activeFate?.id==='F09')this.buyPack('mystery',true);return true};
 const start=P.start;P.start=function(){if(this.state.deck.pendingPack)return{ok:false,message:'Chọn xong các lá giữ lại trong gói trước.'};const result=start.call(this);if(!result.ok)return result;const fate=this.state.deck.activeFate?.id;if(fate==='F08')for(let i=0;i<2;i++)this.state.encounter.spawnQueue.push({species:i?'mage':'knight',name:'Tinh anh của Cuộc Săn',elite:true,reinforcement:false,squadId:'fate-elite'});return result};
 const spawning=P.spawnExpedition;P.spawnExpedition=function(dt){const count=this.state.entities.length;spawning.call(this,dt);if(this.state.deck.activeFate?.id==='F04')for(const e of this.state.entities.slice(count))if(e.faction==='hero'){e.charms=[...new Set([...e.charms,'greedy'])]}};
 const finish=P.finish;P.finish=function(){const battle=this.state.phase==='battle';finish.call(this);if(!battle||this.state.phase!=='result')return;const s=this.state;if(s.deck.activeFate?.id==='F08'){const extra=Math.round(s.result.reward*.7);s.gold+=extra;s.result.reward+=extra}for(const r of s.rooms.filter(r=>r.type==='herbgarden'&&this.roomOperational(r)))s.brewedPotions+=2*r.level;this.prepareFates()};
 P.buySpy=function(){const s=this.state;if(!this.canPrepare()||s.gold<80||s.world.spy?.state==='pending'||s.world.spy?.wave===s.wave)return false;s.gold-=80;s.world.spy={state:'pending',wave:s.wave,readyAt:s.time+20};this.log('Một gián điệp đã giả dạng thương nhân lên đường.');return true};
